import { useCallback, useEffect, useRef, useSyncExternalStore } from 'react'
import { MockMLEngine } from '../mock/ml/engine'
import type { MLDecision, MLSnapshot } from '../mock/ml/engine'

export interface MockMLState extends MLSnapshot {
  sendRequest: (model: string) => MLDecision
  load: (id: string) => void
  kill: (id: string) => void
  revive: (id: string) => void
  reset: () => void
}

/**
 * ML Preview data source. Purely in-browser: no fetch, no XHR, no WebSocket.
 * Every value here is generated by the mock engine and labelled "Mock" in the UI.
 */
export function useMockML(): MockMLState {
  const store = useRef<MockMLEngine | null>(null)
  if (!store.current) store.current = new MockMLEngine()
  const engine = store.current

  const snapshot = useSyncExternalStore(engine.subscribe, engine.getSnapshot, engine.getSnapshot)

  useEffect(() => {
    const timer = window.setInterval(() => engine.tick(), 1000)
    return () => window.clearInterval(timer)
  }, [engine])

  const sendRequest = useCallback((model: string) => engine.send(model), [engine])
  const load = useCallback((id: string) => engine.load(id), [engine])
  const kill = useCallback((id: string) => engine.kill(id), [engine])
  const revive = useCallback((id: string) => engine.revive(id), [engine])
  const reset = useCallback(() => engine.reset(), [engine])

  return { ...snapshot, sendRequest, load, kill, revive, reset }
}
